import {advance,archive,nextEgg} from './growth.mjs?art=8';
import {growthContent,growthNotice} from './growth-view.mjs?art=8';
import {firebaseConfig} from './config.js';
import {initialState,dayKey,approve,validateItem} from './domain.mjs?art=8';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let demo=!firebaseConfig,role='child',tab='chores',state=initialState(),requests=[],joins=[],uid='demo-child',family='',user=null,api=null,stops=[],busy=false,ready=false,member=false,joinStatus='',loadError='';
let inviteFamily=new URLSearchParams(location.hash.slice(1)).get('family')||localStorage.getItem('pocket-family')||'';
if(demo){state.accounts[uid]={name:'きみ',points:70};ready=true;member=true;}
let growthRecords=[],historyCursor=null,moreGrowth=false,growthLoaded=false,seenGrowth=false,lastGrowth=null,celebration=null,growthSyncing=false;
const modal=$('#modal');
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3500)}
function show(html){modal.innerHTML=html;modal.showModal()}
function close(){modal.close()}
function err(e){console.error(e);const code=e.code||'';toast(code.includes('auth/')?'ログインできませんでした。メール・パスワードや接続設定をご確認ください。':code.includes('permission')?'アクセスできません。家族の承認と接続設定をご確認ください。':e.message||'通信できませんでした。もう一度お試しください。')}
function current(){return state.accounts[uid]||Object.values(state.accounts)[0]||{name:'お子さん',points:0}}
function pendingFor(item,type){return requests.find(r=>r.uid===uid&&r.itemId===item.id&&r.type===type&&r.status==='pending'&&(type==='reward'||r.day===dayKey()))}
function doneFor(item){return state.history.some(h=>h.uid===uid&&h.itemId===item.id&&h.type==='chore'&&h.day===dayKey())}
function top(){return `${demo?'<div class="demo-bar">おためしモード · 記録は保存・共有されません <button data-action="setup">家族で使うには</button></div>':''}<header><div class="brand"><img src="icon.svg" alt=""><div>おてつだいポケット<small>OTETSUDAI POCKET</small></div></div><button class="mode" ${!demo&&!user?'hidden':''} data-action="${demo?'switch':'account'}">${demo?(role==='child'?'⚙ 親の画面へ':'☺ 子供の画面へ'):(role==='parent'?'⚙ 家族の設定':'☺ '+esc(current().name))}</button></header>`}
function render(){
 if(!demo&&!user){$('#app').innerHTML=top()+login();return}
 if(!ready){$('#app').innerHTML=top()+`<main><div class="empty">${loadError?esc(loadError):member?'記録を読みこんでいます…':joinStatus==='rejected'?'参加は見送りになりました。おうちの人に確認してください。':'親のスマホで参加を承認すると使えます。'}<p><button data-action="account">アカウント</button></p></div></main>`;return}
 const a=current(),next=[...state.rewards].sort((a,b)=>a.points-b.points).find(r=>r.points>a.points)||state.rewards[0];
 const wait=requests.filter(r=>r.status==='pending').length+joins.length;
 $('#app').innerHTML=top()+`<main><div class="greeting"><div><div class="eyebrow">${role==='parent'?'PARENT’S POCKET':'MY POCKET'}</div><h1>${role==='parent'?'がんばりを、応援しよう。':esc(a.name)+'、今日もよろしく！'}</h1></div><span class="date">${new Intl.DateTimeFormat('ja-JP',{month:'long',day:'numeric',weekday:'short'}).format(new Date())}</span></div><div class="dashboard"><section class="balance"><div class="eyebrow">${role==='parent'?esc(a.name)+'のポイント':'いま持っているポイント'}</div><div class="balance-number">${a.points.toLocaleString()}<span>pt</span></div><div class="coin" aria-hidden="true">★</div><div class="balance-footer">${role==='parent'?'ひとつの「できた！」を、うれしいごほうびに。':'こつこつ貯めて、ごほうびと交換しよう。'}</div></section><section class="next-reward"><div class="eyebrow">つぎの楽しみ</div>${next?`<div class="reward-line"><div class="emoji">${esc(next.emoji)}</div><div><strong>${esc(next.title)}</strong><small>${a.points>=next.points?'交換できるよ！':'あと '+(next.points-a.points)+' ポイント！'}</small></div></div><progress aria-label="ごほうびまでのポイント" max="${next.points}" value="${Math.min(next.points,a.points)}"></progress>`:'<p>親の画面で、ごほうびを登録しよう。</p>'}</section></div><nav class="tabs" aria-label="メニュー">${[['chores','おてつだい'],['rewards','ごほうび'],...(role==='parent'?[['approve','承認'+(wait?' '+wait:'')]]:[]),['growth','そだてる'],['history','きろく']].map(([k,v])=>`<button data-tab="${k}" class="${tab===k?'active':''}" aria-current="${tab===k?'page':'false'}">${v}</button>`).join('')}</nav>${tab!=='growth'?growthNotice(state.growth):''}${content()}<p class="footer-note">小さなおてつだいが、大きな「ありがとう」に。</p></main>`;
}
function content(){
 if(tab==='growth')return growthContent(state.growth,role,growthRecords,moreGrowth,celebration,growthLoaded);

 if(tab==='history')return `<div class="section-head"><h2>ポイントのきろく</h2><span class="pill">${state.history.length}件</span></div><div class="list">${state.history.filter(h=>role==='parent'||h.uid===uid).map(h=>`<div class="history-row"><div class="emoji">${esc(h.emoji)}</div><div class="grow"><strong>${esc(h.title)}</strong><small>${esc(h.name)} · ${new Date(h.at).toLocaleDateString('ja-JP')} · ${h.delta>0?'おてつだい達成':'交換ずみ'}</small></div><span class="delta ${h.delta<0?'negative':''}">${h.delta>0?'+':''}${h.delta}<small> pt</small></span></div>`).join('')||'<div class="empty">まだきろくはないよ。<br>最初のおてつだいにチャレンジしよう！</div>'}</div>`;
 if(tab==='approve')return `<div class="section-head"><div><h2>届いているリクエスト</h2><p>内容を確認して、承認してください。</p></div></div><div class="list">${joins.map(j=>`<article class="card stacked"><div class="emoji">🙋</div><div class="card-body"><h3>${esc(j.name)}が家族に参加します</h3><span class="pending">子供のスマホからの参加申請</span></div><div class="actions"><button data-action="joinReject" data-id="${esc(j.id)}">見送る</button><button class="primary" data-action="joinAccept" data-id="${esc(j.id)}">参加を承認</button></div></article>`).join('')}${requests.filter(r=>r.status==='pending').map(r=>{const i=(r.type==='chore'?state.chores:state.rewards).find(i=>i.id===r.itemId);return `<article class="card stacked"><div class="emoji">${esc(i?.emoji||'📩')}</div><div class="card-body"><h3>${esc(i?.title||'削除された項目')}</h3><span class="pending">${esc(state.accounts[r.uid]?.name||'子供')} · ${r.type==='chore'?'できた！':'交換したい！'} · ${esc(r.day)}</span><div class="points">${i?`${r.type==='chore'?'+':'−'}${i.points} pt`:''}</div></div><div class="actions"><button data-action="reject" data-id="${esc(r.id)}">見送る</button><button class="primary" data-action="approve" data-id="${esc(r.id)}">承認する</button></div></article>`}).join('')||(!joins.length?'<div class="empty">確認待ちはありません。<br>お子さんからの「できた！」を待ちましょう。</div>':'')}</div>`;
 const isChore=tab==='chores',items=isChore?state.chores:state.rewards;
 return `<div class="section-head"><div><h2>${isChore?'今日のおてつだい':'ごほうびをえらぼう'}</h2><p>${isChore?'できることから、ひとつずつ。':'ポイントを貯めて、楽しみをふやそう。'}</p></div>${role==='parent'?`<button class="primary small" data-action="add">＋ ${isChore?'おてつだい':'ごほうび'}を追加</button>`:`<span class="pill">${items.length}つの${isChore?'おてつだい':'ごほうび'}</span>`}</div><div class="cards">${items.map(i=>{const pending=pendingFor(i,isChore?'chore':'reward'),done=isChore&&doneFor(i),lack=!isChore&&current().points<i.points;return `<article class="card"><div class="emoji">${esc(i.emoji)}</div><div class="card-body"><h3>${esc(i.title)}</h3><span class="points">${isChore?'+ ':''}${i.points} pt</span>${pending?'<div class="pending">おうちの人が確認中</div>':''}</div>${role==='parent'?`<button class="small" data-action="edit" data-id="${i.id}" aria-label="${esc(i.title)}を編集">編集</button>`:`<button class="${isChore?'primary':'yellow'}" data-action="request" data-id="${i.id}" ${pending||done||lack?'disabled':''}>${pending?'確認中':done?'✓ できた':isChore?'できた！':lack?'あと '+(i.points-current().points)+' pt':'交換する'}</button>`}</article>`}).join('')||'<div class="empty">まだ登録されていません。</div>'}</div>${role==='child'?`<div class="notice">${isChore?'💡 おうちの人が確認すると、ポイントがもらえるよ。おてつだいは1つにつき1日1回。':'🎁 おうちの人が交換をOKすると、ポイントがひかれるよ。'}</div>`:''}`;
}
function login(){return `<main><section class="login"><div class="eyebrow">WELCOME TO YOUR POCKET</div><h1>${inviteFamily?'家族のポケットに参加':'家族の「できた！」を貯めよう'}</h1><p>${inviteFamily?'お子さんの呼び名を入れてください。親のスマホで承認すると使えます。':'親のメールアドレスで始めましょう。子供のスマホには、あとで招待リンクを送れます。'}</p><form id="login-form">${inviteFamily?'<label for="name">呼び名</label><input id="name" name="name" maxlength="20" required autocomplete="nickname">':'<label for="email">親のメールアドレス</label><input id="email" name="email" type="email" required autocomplete="email"><label for="password">パスワード（8文字以上）</label><input id="password" name="password" type="password" minlength="8" required autocomplete="current-password">'}<button class="primary" name="intent" value="login">${inviteFamily?'家族に参加する':'ログイン'}</button>${!inviteFamily?'<button class="ghost" type="submit" name="intent" value="register">はじめて使う（親の登録）</button><button class="ghost" type="button" data-action="resetPassword">パスワードを忘れた方</button>':''}</form></section></main>`}
function edit(id){const type=tab==='chores'?'chores':'rewards',i=state[type].find(i=>i.id===id);show(`<h2>${i?'編集する':type==='chores'?'おてつだいを追加':'ごほうびを追加'}</h2><form id="item-form" data-type="${type}" data-id="${i?.id||''}"><label for="title">名前</label><input id="title" name="title" required maxlength="40" value="${esc(i?.title||'')}"><label for="points">${type==='chores'?'もらえる':'交換に必要な'}ポイント</label><input id="points" name="points" type="number" min="1" max="10000" step="1" required value="${i?.points||10}"><label for="emoji">マーク</label><select id="emoji" name="emoji">${['🍽️','👕','🌱','🧹','🧸','🐾','🍩','🎮','🎡','📚','🎨','⭐'].map(e=>`<option ${e===i?.emoji?'selected':''}>${e}</option>`).join('')}</select><div class="actions">${i?'<button type="button" data-action="delete" data-id="'+i.id+'">削除</button>':''}<button type="button" data-action="close">やめる</button><button class="primary" type="submit">保存する</button></div></form>`)}
async function mutate(fn){if(demo){state=fn(structuredClone(state));render();return}await api.runTransaction(api.db,async tx=>{const ref=api.doc(api.db,'families',family);const snap=await tx.get(ref);tx.set(ref,fn(snap.data()));});}
async function sendRequest(id){const type=tab==='chores'?'chore':'reward',i=(type==='chore'?state.chores:state.rewards).find(i=>i.id===id);if(!i)throw new Error('項目が見つかりません。');if(pendingFor(i,type)||type==='chore'&&doneFor(i))throw new Error('すでに送っています。');if(type==='reward'&&current().points<i.points)throw new Error('ポイントが足りません。');const key=type==='chore'?`${uid}_${id}_${dayKey()}`:crypto.randomUUID();const r={uid,type,itemId:id,day:dayKey(),status:'pending',at:Date.now()};if(demo){const old=requests.find(r=>r.id===key);if(old&&old.status!=='rejected')throw new Error('このお手伝いは今日は申請済みです。');if(old)Object.assign(old,r);else requests.push({...r,id:key});render()}else await api.setDoc(api.doc(api.db,'families',family,'requests',key),r);toast(type==='chore'?'「できた！」を送ったよ！':'交換を申しこんだよ！');}
async function decide(id,accept){const seed=crypto.randomUUID(),now=Date.now();if(role!=='parent')throw new Error('親の操作が必要です。');if(demo){const r=requests.find(r=>r.id===id);if(!r||r.status!=='pending')throw new Error('すでに処理されています。');if(accept){const previous=state.growth;state=approve(state,r,id,Date.now(),seed);saveDemoArchive(previous,state.growth);observeGrowth(state.growth);}r.status=accept?'approved':'rejected';render()}else await api.runTransaction(api.db,async tx=>{const ref=api.doc(api.db,'families',family),rr=api.doc(api.db,'families',family,'requests',id);const [s,r]=await Promise.all([tx.get(ref),tx.get(rr)]);if(!r.exists()||r.data().status!=='pending')throw new Error('すでに処理されています。');if(accept){const next=approve(s.data(),r.data(),id,now,seed);writeGrowthArchive(tx,s.data().growth,next.growth);tx.set(ref,next);}tx.update(rr,{status:accept?'approved':'rejected'});});toast(accept?'承認しました！':'見送りにしました');}
async function handle(action,id){
 if(action==='growthMore'){await loadGrowthHistory(true);return}
 if(action==='nextEgg'){if(role!=='parent')return;show('<h2>新しいタマゴを迎える？</h2><p>育った子は図鑑に残ります。次の子は成長0ポイントから始まります。</p><div class="actions"><button data-action="close">やめる</button><button class="primary" data-action="nextEggConfirm" data-id="'+esc(state.growth.id)+'">迎える</button></div>');return}
 if(action==='nextEggConfirm'){if(role!=='parent')throw Error('親の操作が必要です');const cycleId=crypto.randomUUID();await mutate(s=>{if(s.growth?.id!==id)throw Error('すでに次の育成が始まっています');return {...s,growth:nextEgg(s.growth,cycleId)}});celebration=null;close();return}
 if(action==='close')return close();if(action==='switch'){role=role==='child'?'parent':'child';tab='chores';render();return}
 if(action==='setup'){show('<h2>家族で使いはじめる</h2><p>今は操作を試せるおためし版です。親と子供のスマホで共有するには、Firebaseへの接続設定が必要です。</p><p>接続後は、親が登録 → 招待リンクを子供に送る → 参加を承認、の3ステップで使えます。</p><div class="actions"><button data-action="close" class="primary">わかった</button></div>');return}
 if(action==='add'||action==='edit'){if(role!=='parent')return;edit(id);return}
 if(action==='request'){const i=(tab==='chores'?state.chores:state.rewards).find(i=>i.id===id);show(`<h2>${tab==='chores'?'できた！を送る？':'ごほうびを申しこむ？'}</h2><p>${esc(i.title)} · ${i.points} pt</p><p>${tab==='chores'?'おうちの人が確認したら、ポイントがもらえるよ。':'おうちの人がOKすると、ポイントがひかれるよ。'}</p><div class="actions"><button data-action="close">やめる</button><button class="primary" data-action="send" data-id="${id}">送る</button></div>`);return}
 if(action==='send'){await sendRequest(id);close();return}
 if(action==='approve'||action==='reject'){await decide(id,action==='approve');return}
 if(action==='delete'){const type=$('#item-form').dataset.type;show(`<h2>この項目を削除しますか？</h2><p>過去のきろくは残ります。確認待ちの申請は、見送りにしてください。</p><div class="actions"><button data-action="close">やめる</button><button class="primary" data-action="deleteConfirm" data-id="${id}" data-type="${type}">削除する</button></div>`);return}
 if(action==='deleteConfirm'){const type=modal.querySelector('[data-type]').dataset.type;await mutate(s=>({...s,[type]:s[type].filter(i=>i.id!==id)}));close();toast('削除しました');return}
 if(action==='account'){const url=location.origin+location.pathname+'#family='+family;show(`<h2>${role==='parent'?'家族の設定':'このスマホ'}</h2>${role==='parent'?`<p>このリンクを子供のスマホで開いて、参加を申しこんでください。続けて、親の「承認」画面で参加を承認します。</p><div class="invite">${esc(url)}</div><button data-action="copyInvite">招待リンクをコピー</button>`:'<p>このスマホは子供用です。ログアウトやブラウザのデータ削除後は、もう一度招待リンクから参加して、親に承認してもらってください。</p>'}<div class="actions"><button data-action="close">閉じる</button><button data-action="logout">ログアウト</button></div>`);return}
 if(action==='copyInvite'){await navigator.clipboard.writeText(location.origin+location.pathname+'#family='+family);toast('招待リンクをコピーしました');return}
 if(action==='logout'){close();stops.forEach(f=>f());stops=[];localStorage.removeItem('pocket-family');inviteFamily='';location.hash='';await api.signOut(api.auth);return}
 if(action==='resetPassword'){const email=$('#email').value;if(!email){toast('メールアドレスを入力してください');return}await api.sendPasswordResetEmail(api.auth,email);toast('再設定のメールを送信しました');return}
 if(action==='joinAccept'&&Object.keys(state.accounts).length&&!state.accounts[id]){show(`<h2>子供のスマホを入れ替えますか？</h2><p>今のポイントときろくを、新しいスマホに引き継ぎます。以前のスマホは使えなくなります。</p><div class="actions"><button data-action="close">やめる</button><button class="primary" data-action="joinReplace" data-id="${esc(id)}">引き継ぐ</button></div>`);return}
 if(action==='joinAccept'||action==='joinReject'||action==='joinReplace'){await api.runTransaction(api.db,async tx=>{const jr=api.doc(api.db,'families',family,'joins',id),fr=api.doc(api.db,'families',family);const [j,s]=await Promise.all([tx.get(jr),tx.get(fr)]);if(!j.exists()||j.data().status!=='pending')throw new Error('処理済みです');if(action==='joinAccept'||action==='joinReplace'){const data=s.data();const old=Object.keys(data.accounts).find(k=>k!==id);if(old&&action!=='joinReplace')throw new Error('子供のスマホが変更されています。もう一度操作してください。');let points=data.accounts[id]?.points||0;if(old){points=data.accounts[old].points;delete data.accounts[old];data.history=data.history.map(h=>h.uid===old?{...h,uid:id}:h);tx.delete(api.doc(api.db,'families',family,'members',old));}data.accounts[id]={name:j.data().name,points};tx.set(fr,data);tx.set(api.doc(api.db,'families',family,'members',id),{name:j.data().name});}tx.update(jr,{status:action==='joinReject'?'rejected':'approved'});});if(modal.open)close();toast('参加申請を処理しました');return}
}
document.addEventListener('click',async e=>{const t=e.target.closest('button');if(!t)return;if(t.dataset.tab){tab=t.dataset.tab;render();if(tab==='growth'&&!growthLoaded)loadGrowthHistory().catch(err);return}if(!t.dataset.action||busy)return;busy=true;t.disabled=true;try{await handle(t.dataset.action,t.dataset.id)}catch(e){err(e)}finally{busy=false;if(t.isConnected)t.disabled=false}});
document.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;busy=true;const form=e.target,btn=e.submitter;if(btn)btn.disabled=true;try{const f=new FormData(form);if(form.id==='item-form'){if(role!=='parent')throw new Error('親の操作が必要です');const title=f.get('title').trim(),points=Number(f.get('points'));validateItem(title,points);const type=form.dataset.type,id=form.dataset.id||crypto.randomUUID(),item={id,title,points,emoji:f.get('emoji')};await mutate(s=>{const idx=s[type].findIndex(i=>i.id===id);if(idx<0)s[type].push(item);else s[type][idx]=item;return s});close();toast('保存しました')}else if(form.id==='login-form'){if(inviteFamily){localStorage.setItem('pocket-family',inviteFamily);const {user:u}=await api.signInAnonymously(api.auth);await api.setDoc(api.doc(api.db,'families',inviteFamily,'joins',u.uid),{name:f.get('name').trim()||'こども',status:'pending'});}else if(btn.value==='register')await api.createUserWithEmailAndPassword(api.auth,f.get('email'),f.get('password'));else await api.signInWithEmailAndPassword(api.auth,f.get('email'),f.get('password'));}}catch(e){err(e)}finally{busy=false;if(btn?.isConnected)btn.disabled=false}});
function syncError(e){loadError='記録を読みこめませんでした。接続と設定を確認して、再読み込みしてください。';ready=false;err(e);render()}
async function connect(){try{const [app,auth,db]=await Promise.all([import('https://www.gstatic.com/firebasejs/12.19.0/firebase-app.js'),import('https://www.gstatic.com/firebasejs/12.19.0/firebase-auth.js'),import('https://www.gstatic.com/firebasejs/12.19.0/firebase-firestore.js')]);const instance=app.initializeApp(firebaseConfig);api={...auth,...db,auth:auth.getAuth(instance),db:db.getFirestore(instance)};auth.onAuthStateChanged(api.auth,async u=>{stops.forEach(f=>f());stops=[];user=u;ready=false;member=false;loadError='';joinStatus='';state=initialState();requests=[];joins=[];growthRecords=[];growthLoaded=false;historyCursor=null;moreGrowth=false;seenGrowth=false;lastGrowth=null;celebration=null;if(!u){render();return}uid=u.uid;role=u.isAnonymous?'child':'parent';family=role==='parent'?uid:inviteFamily;try{if(!family)throw new Error('親からの招待リンクで開き直してください。');if(role==='parent'){const ref=db.doc(api.db,'families',family);await db.runTransaction(api.db,async tx=>{const snap=await tx.get(ref);if(!snap.exists())tx.set(ref,initialState())});member=true;watchFamily();stops.push(db.onSnapshot(db.query(db.collection(api.db,'families',family,'joins'),db.where('status','==','pending')),s=>{joins=s.docs.map(d=>({...d.data(),id:d.id}));render()},err))}else{stops.push(db.onSnapshot(db.doc(api.db,'families',family,'joins',uid),s=>{joinStatus=s.data()?.status||'';render()},syncError));stops.push(db.onSnapshot(db.doc(api.db,'families',family,'members',uid),s=>{member=s.exists();if(member&&!ready)watchFamily();else if(!member){ready=false;state=initialState();requests=[];render()}},syncError))}render()}catch(e){syncError(e)}})}catch(e){err(e);$('#app').innerHTML=top()+'<main><div class="empty">接続できませんでした。インターネット接続を確認して、再読み込みしてください。</div></main>'}}
function watchFamily(){stops.push(api.onSnapshot(api.doc(api.db,'families',family),s=>{if(s.exists()){state=s.data();observeGrowth(state.growth);ready=true;loadError='';render();refreshGrowth().catch(err)}},syncError));let q=api.query(api.collection(api.db,'families',family,'requests'),api.where('status','==','pending'));if(role==='child')q=api.query(q,api.where('uid','==',uid));stops.push(api.onSnapshot(q,s=>{requests=s.docs.map(d=>({...d.data(),id:d.id}));render()},syncError));}
function observeGrowth(g){
 if(seenGrowth&&g&&g.id===lastGrowth?.id&&g.lastEvent!==lastGrowth.lastEvent){celebration={stage:g.stage,at:Date.now(),evolved:g.stage>lastGrowth.stage};toast(g.stage>lastGrowth.stage?'なんだか様子が違う……新しい姿になったよ！':'おてつだい、ありがとう！ 成長 +10');if(g.stage===4){growthLoaded=false;if(tab==='growth')loadGrowthHistory().catch(err)}}
 else if(seenGrowth&&g&&!lastGrowth){celebration={stage:g.stage,at:Date.now(),evolved:true};toast('タマゴから生まれたよ！')}
 seenGrowth=true;lastGrowth=g?structuredClone(g):null;
}
function saveDemoArchive(before,after){if(before?.stage!==4&&after?.stage===4)growthRecords.unshift(archive(after))}
function writeGrowthArchive(tx,before,after){if(before?.stage!==4&&after?.stage===4)tx.set(api.doc(api.db,'families',family,'growthHistory',after.id),archive(after))}
async function refreshGrowth(){
 if(role!=='parent'||!ready||growthSyncing||!state.growth||state.growth.stage===4)return;
 const now=Date.now(),seed=crypto.randomUUID();if(advance(state.growth,now,seed).stage===state.growth.stage)return;
 growthSyncing=true;try{if(demo){const before=state.growth;state.growth=advance(before,now,seed);saveDemoArchive(before,state.growth);observeGrowth(state.growth);render()}else await api.runTransaction(api.db,async tx=>{const ref=api.doc(api.db,'families',family),snap=await tx.get(ref);const before=snap.data().growth;if(!before)return;const after=advance(before,now,seed);if(after.stage===before.stage)return;writeGrowthArchive(tx,before,after);tx.update(ref,{growth:after})})}finally{growthSyncing=false}
}
async function loadGrowthHistory(more=false){
 if(demo){growthLoaded=true;render();return}if(!ready)return;
 const requestedFamily=family,requestedUid=uid;
 const clauses=[api.orderBy('completedAt','desc'),api.orderBy(api.documentId(),'desc')];if(more&&historyCursor)clauses.push(api.startAfter(historyCursor));clauses.push(api.limit(25));
 const snap=await api.getDocs(api.query(api.collection(api.db,'families',family,'growthHistory'),...clauses));
 if(family!==requestedFamily||uid!==requestedUid||!ready)return;
 const rows=snap.docs.map(d=>d.data());growthRecords=more?[...new Map([...growthRecords,...rows].map(r=>[r.cycleId,r])).values()]:rows;historyCursor=snap.docs.at(-1)||null;moreGrowth=rows.length===25;growthLoaded=true;render();
}
setInterval(()=>{if(document.visibilityState==='visible'){refreshGrowth().catch(err);if(tab==='growth'&&ready)render()}},60000);
window.addEventListener('focus',()=>refreshGrowth().catch(err));
if(demo)observeGrowth(state.growth);
render();if(!demo)connect();
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(console.warn);
if(document.modelContext?.registerTool){document.modelContext.registerTool({name:'read_pocket',title:'ポイントとお手伝いを見る',description:'現在の利用者に表示されているお手伝い、ごほうび、ポイントを取得します。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:(input)=>{if(!input||Object.keys(input).length)throw new Error('引数は不要です');if(!ready)throw new Error('家族への参加が必要です');return {demo,role,points:current().points,chores:state.chores,rewards:state.rewards}}});}
